let s=new Session({queryFn:({signal})=>{calls++; assert.equal(signal.aborted,false); return 'fresh';},timers:{schedule:fn=>setTimeout(fn,0)}},{online:false});
const h=s.subscribe('station');
assert.deepEqual(s.snapshot('station'),{status:'pending',fetchStatus:'paused',data:null});
s.unsubscribe(h);
assert.deepEqual(s.snapshot('station'),{status:'pending',fetchStatus:'idle',data:null});
s.online(true); await tick();
assert.equal(calls,0);
const h2=s.subscribe('station');
assert.equal(calls,1); await tick();
assert.deepEqual(s.snapshot('station'),{status:'success',fetchStatus:'idle',data:'fresh'});
s.unsubscribe(h2);

calls=0;
s=new Session({queryFn:()=>{calls++; return 'updated';},timers:{schedule:fn=>setTimeout(fn,0)}},{online:false});
const cached=s.subscribe('station',{initialData:'cached'});
s.unsubscribe(cached); s.online(true); await tick(); await tick();
assert.equal(calls,1);
assert.deepEqual(s.snapshot('station'),{status:'success',fetchStatus:'idle',data:'updated'});

let resolve;
calls=0;
s=new Session({queryFn:()=>{calls++; return new Promise(r=>resolve=r);},timers:{schedule:fn=>setTimeout(fn,0)}});
const active=s.subscribe('station'); s.unsubscribe(active); assert.equal(calls,1); resolve('done'); await tick();
assert.deepEqual(s.snapshot('station'),{status:'success',fetchStatus:'idle',data:'done'});

let received;
s=new Session({queryFn:({signal})=>{received=signal; return new Promise(()=>{});},timers:{schedule:fn=>setTimeout(fn,0)}});
