assert.equal(received.aborted,true);
assert.deepEqual(s.snapshot('station'),{status:'pending',fetchStatus:'idle',data:null});

calls=0;
s=new Session({queryFn:()=>{calls++; return new Promise(()=>{});},timers:{schedule:fn=>setTimeout(fn,0)}},{online:false});
