import assert from 'node:assert/strict';
import { Session } from './src/session.js';
const flush=()=>Promise.resolve();
const timers={schedule:fn=>setTimeout(fn,0)};
let calls=0;
let s=new Session({timers,queryFn(){calls++;return 'x'}},{online:false});
let h=s.subscribe('fresh'); assert.equal(s.snapshot('fresh').fetchStatus,'paused'); s.unsubscribe(h); assert.equal(s.snapshot('fresh').fetchStatus,'idle'); s.online(true); await flush(); assert.equal(calls,0);
h=s.subscribe('fresh'); assert.equal(calls,1); await flush(); assert.equal(s.snapshot('fresh').data,'x');
// A resume that was queued must be invalidated by a later unmount.
calls=0;s=new Session({timers,queryFn(){calls++;return 'x'}},{online:false});h=s.subscribe('queued');s.online(true);s.unsubscribe(h);await flush();assert.equal(calls,0);assert.equal(s.snapshot('queued').fetchStatus,'idle');
// Started unconsumed work remains valid after the observer leaves.
let release;calls=0;s=new Session({timers,queryFn(){calls++;return new Promise(r=>release=r)}},{online:true});h=s.subscribe('running');s.unsubscribe(h);release('done');await flush();assert.equal(calls,1);assert.equal(s.snapshot('running').data,'done');
// A paused refresh with cached data remains resumable without observers.
calls=0;s=new Session({timers,queryFn(){calls++;return 'cached'}},{online:false});h=s.subscribe('cache',{initialData:'old'});s.unsubscribe(h);s.online(true);await flush();assert.equal(calls,1);await flush();assert.equal(s.snapshot('cache').data,'cached');
console.log('lifecycle assertions passed');
